frappe.ui.form.on('Employee', {
    validate(frm) {
        if (frm.doc.custom_aadhar_card_number) {

            const aadhar =

                frm.doc.custom_aadhar_card_number

                    .replace(/\s+/g, '');

            if (!/^\d{12}$/.test(aadhar)) {

                frappe.throw(

                    'Aadhar Card Number must contain exactly 12 digits'

                );

            }

            // Direct assignment

            frm.doc.custom_aadhar_card_number = aadhar;

        }

        // PAN Validation

        if (frm.doc.pan_number) {

            const pan =

                frm.doc.pan_number

                    .toUpperCase();

            if (!/^[A-Z]{5}[0-9]{4}[A-Z]{1}$/.test(pan)) {

                frappe.throw(

                    'Invalid PAN Card Number Format'

                );

            }

            // Direct assignment

            frm.doc.custom_pan_number = pan;

        }

    },
    refresh(frm) {

        render_document_preview_buttons(frm);

        const is_employee_self_service =
            frappe.user.has_role("Employee Self Service");

        const is_hr_or_admin =
            frappe.user.has_role("HR Manager") ||
            frappe.user.has_role("HR User") ||
            frappe.user.has_role("System Manager");

        if (!is_employee_self_service || is_hr_or_admin) {
            return;
        }

        const editable_sections = [
            "personal_details_section",
            "emergency_contact_section",
            "custom_aadhar",
            "bank_details_section",
            "custom_section_break_y1u7h",
            "address_section",
            "emergency_contact_details",
            "custom_nominee_details"
        ];

        const skip_fieldtypes = [
            "Section Break",
            "Column Break",
            "Tab Break",
            "HTML",
            "Button"
        ];

        // Make readonly
        frm.fields.forEach(field => {

            if (
                !field.df.fieldname ||
                skip_fieldtypes.includes(field.df.fieldtype)
            ) {
                return;
            }

            frm.set_df_property(
                field.df.fieldname,
                "read_only",
                1
            );
        });

        // Allow editable sections
        let allow = false;

        frm.fields.forEach(field => {

            if (field.df.fieldtype === "Section Break") {

                allow = editable_sections.includes(
                    field.df.fieldname
                );

                return;
            }

            if (
                !field.df.fieldname ||
                skip_fieldtypes.includes(field.df.fieldtype)
            ) {
                return;
            }

            if (allow) {

                frm.set_df_property(
                    field.df.fieldname,
                    "read_only",
                    0
                );
            }
        });
    },

    custom_aadhar_card(frm) {
        render_document_preview_buttons(frm);
    },

    custom_pan_card(frm) {
        render_document_preview_buttons(frm);
    }
});


function render_document_preview_buttons(frm) {

    const fields = [
        {
            label: "Aadhar Card",
            fieldname: "custom_aadhar_card"
        },
        {
            label: "PAN Card",
            fieldname: "custom_pan_card"
        }
    ];

    let html = `
        <div style="
            display:flex;
            gap:10px;
            flex-wrap:wrap;
        ">
    `;

    fields.forEach(doc => {

        const file_url = frm.doc[doc.fieldname];

        if (!file_url) {
            return;
        }

        html += `
            <button
                class="btn btn-default btn-sm preview-document-btn"
                data-file="${file_url}"
                data-label="${doc.label}"
                style="margin-bottom:10px"
            >
                Preview ${doc.label}
            </button>
        `;
    });

    html += `</div>`;

    frm.fields_dict.custom_document_preview.$wrapper.html(html);

    // Button click
    frm.fields_dict.custom_document_preview.$wrapper
        .find('.preview-document-btn')
        .on('click', function () {

            const file_url = $(this).data('file');
            const label = $(this).data('label');

            open_document_preview_dialog(file_url, label);
        });
}


function open_document_preview_dialog(file_url, label) {

    const extension = file_url
        .split('.')
        .pop()
        .toLowerCase();

    let content = '';

    // Image Preview
    if ([
        'jpg',
        'jpeg',
        'png',
        'webp'
    ].includes(extension)) {

        content = `
            <div style="text-align:center">
                <img
                    src="${file_url}"
                    style="
                        max-width:100%;
                        max-height:75vh;
                        border-radius:10px;
                    "
                />
            </div>
        `;
    }

    // PDF Preview
    else if (extension === 'pdf') {

        content = `
            <iframe
                src="${file_url}"
                width="100%"
                height="700px"
                style="border:none"
            ></iframe>
        `;
    }

    // Other Files
    else {

        content = `
            <div style="padding:20px;text-align:center">
                <a
                    href="${file_url}"
                    target="_blank"
                    class="btn btn-primary"
                >
                    Open File
                </a>
            </div>
        `;
    }

    const dialog = new frappe.ui.Dialog({
        title: label,
        size: 'extra-large',
        fields: [
            {
                fieldtype: 'HTML',
                fieldname: 'preview_html'
            }
        ]
    });

    dialog.fields_dict.preview_html.$wrapper.html(content);

    dialog.show();
}

frappe.listview_settings["Shift Type"] = {

    onload(listview) {

        listview.page.add_inner_button(
            "Regularize Shift Attendance",
            () => {

                const d = new frappe.ui.Dialog({

                    title: "Regularize Shift Attendance",

                    fields: [

                        {
                            label: "Shift Type",
                            fieldname: "shift_type",
                            fieldtype: "Link",
                            options: "Shift Type"
                        },

                        {
                            label: "Employee",
                            fieldname: "employee",
                            fieldtype: "Link",
                            options: "Employee"
                        },

                        {
                            label: "From Date",
                            fieldname: "from_date",
                            fieldtype: "Date",
                            reqd: 1,
                            default: frappe.datetime.month_start()
                        },

                        {
                            label: "To Date",
                            fieldname: "to_date",
                            fieldtype: "Date",
                            reqd: 1,
                            default: frappe.datetime.month_end()
                        }

                    ],

                    primary_action_label: "Run",

                    async primary_action(values) {

                        if (
                            values.from_date > values.to_date
                        ) {
                            frappe.msgprint(
                                __("From Date cannot be greater than To Date")
                            );

                            return;
                        }

                        frappe.call({

                            method:
                                "regularize_consecutive_shift",

                            args: values,

                            freeze: true,

                            freeze_message:
                                __("Regularizing shifts..."),

                            callback(r) {

                                let message =
                                    r.message?.message || r.message;

                                if (Array.isArray(message)) {
                                    message = message.join("<br>");
                                }

                                frappe.msgprint({
                                    title: __("Result"),
                                    message: message || __("Completed")
                                });

                                d.hide();

                                listview.refresh();

                            }

                        });

                    }

                });

                d.show();

            }
        );

    }

};

frappe.ui.form.on("Employee", {

    refresh(frm) {

        if (frm.is_new()) {
            return;
        }

        // Avoid duplicate button
        frm.remove_custom_button(
            __("Employee Documents")
        );

        // Standalone button
        frm.add_custom_button(
            __("Employee Documents"),
            function () {
                open_employee_documents(frm);
            }
        );

        // Add some styling
        add_employee_document_styles();
    }
});


// ============================================================
// DOCUMENT CONFIGURATION
// ============================================================

const EMPLOYEE_DOCUMENT_TYPES = {

    AADHAAR_CARD: {
        label: "Aadhaar Card",
        required: true,
        accept: ".pdf,.jpg,.jpeg,.png,.webp"
    },

    PAN_CARD: {
        label: "PAN Card",
        required: true,
        accept: ".pdf,.jpg,.jpeg,.png,.webp"
    },

    RESUME: {
        label: "Resume",
        required: true,
        accept: ".pdf,.doc,.docx"
    },

    EDUCATION_CERTIFICATE: {
        label: "Education Certificate",
        required: false,
        accept: ".pdf,.jpg,.jpeg,.png,.webp"
    },

    EXPERIENCE_LETTER: {
        label: "Experience Letter",
        required: false,
        accept: ".pdf,.jpg,.jpeg,.png,.webp"
    },

    ADDRESS_PROOF: {
        label: "Address Proof",
        required: false,
        accept: ".pdf,.jpg,.jpeg,.png,.webp"
    },

    BANK_PROOF: {
        label: "Bank Proof",
        required: false,
        accept: ".pdf,.jpg,.jpeg,.png,.webp"
    },

    OTHER: {
        label: "Other",
        required: false,
        accept: ".pdf,.jpg,.jpeg,.png,.webp,.doc,.docx"
    }
};


// ============================================================
// OPEN MODAL
// ============================================================

async function open_employee_documents(frm) {

    const dialog = new frappe.ui.Dialog({

        title: __("Employee Documents"),

        size: "extra-large",

        fields: [
            {
                fieldtype: "HTML",
                fieldname: "documents_html"
            }
        ],

        primary_action_label: __("Close"),

        primary_action() {
            dialog.hide();
        }
    });


    dialog.show();


    await load_employee_documents(
        frm,
        dialog
    );
}


// ============================================================
// LOAD DOCUMENTS
// ============================================================

async function load_employee_documents(
    frm,
    dialog
) {

    const wrapper =
        dialog.fields_dict
            .documents_html
            .$wrapper;


    wrapper.html(`
        <div class="employee-documents-loading">
            <div class="text-muted">
                Loading documents...
            </div>
        </div>
    `);


    try {

        const response =
            await frappe.call({

                method:
                    "employee_document_manager",

                args: {

                    action:
                        "list",

                    employee:
                        frm.doc.name
                }
            });


        const files =
            response.message || [];


        render_employee_documents(
            frm,
            dialog,
            files
        );


    } catch (error) {

        console.error(
            "Document loading error:",
            error
        );


        wrapper.html(`
            <div class="alert alert-danger">
                Unable to load employee documents.
            </div>
        `);
    }
}


// ============================================================
// RENDER DOCUMENTS
// ============================================================

function render_employee_documents(
    frm,
    dialog,
    files
) {

    const wrapper =
        dialog.fields_dict
            .documents_html
            .$wrapper;


    let html = `

        <div class="employee-document-manager">

            <div class="employee-document-header">

                <div>
                    <div class="employee-document-title">
                        Employee Documents
                    </div>

                    <div class="text-muted">
                        Upload and manage documents for
                        ${escape_html(
                            frm.doc.employee_name ||
                            frm.doc.name
                        )}
                    </div>
                </div>

                <div class="employee-document-summary">
                    ${files.length} document(s)
                </div>

            </div>


            <div class="employee-document-grid">
    `;


    Object.keys(
        EMPLOYEE_DOCUMENT_TYPES
    ).forEach(
        document_type => {

            const config =
                EMPLOYEE_DOCUMENT_TYPES[
                    document_type
                ];


            const file =
                files.find(
                    f =>
                        f.document_type ===
                        document_type
                );


            html +=
                render_document_card(
                    document_type,
                    config,
                    file
                );
        }
    );


    html += `

            </div>

        </div>
    `;


    wrapper.html(html);


    // --------------------------------------------------------
    // Bind events
    // --------------------------------------------------------

    wrapper
        .find(".employee-document-upload")
        .on("click", function () {

            const document_type =
                $(this).attr(
                    "data-document-type"
                );

            select_employee_document(
                frm,
                dialog,
                document_type
            );
        });


    wrapper
        .find(".employee-document-preview")
        .on("click", function () {

            const file_name =
                $(this).attr(
                    "data-file-name"
                );

            const file_url =
                $(this).attr(
                    "data-file-url"
                );

            preview_employee_document(
                file_name,
                file_url
            );
        });


    wrapper
        .find(".employee-document-delete")
        .on("click", function () {

            const file_name =
                $(this).attr(
                    "data-file-name"
                );

            delete_employee_document(
                frm,
                dialog,
                file_name
            );
        });
}


// ============================================================
// DOCUMENT CARD
// ============================================================

function render_document_card(
    document_type,
    config,
    file
) {

    const required_badge =
        config.required
            ? `<span class="employee-document-required">
                    Required
               </span>`
            : `<span class="employee-document-optional">
                    Optional
               </span>`;


    if (!file) {

        return `

            <div class="employee-document-card">

                <div class="employee-document-card-header">

                    <div class="employee-document-name">
                        ${escape_html(
                            config.label
                        )}
                    </div>

                    ${required_badge}

                </div>


                <div class="employee-document-empty">

                    <div class="employee-document-icon">
                        📄
                    </div>

                    <div class="text-muted">
                        Document not uploaded
                    </div>

                </div>


                <div class="employee-document-actions">

                    <button
                        type="button"
                        class="btn btn-sm btn-primary employee-document-upload"
                        data-document-type="${document_type}"
                    >
                        Upload
                    </button>

                </div>

            </div>
        `;
    }


    return `

        <div class="employee-document-card employee-document-uploaded">

            <div class="employee-document-card-header">

                <div class="employee-document-name">
                    ${escape_html(
                        config.label
                    )}
                </div>

                <span class="employee-document-success">
                    ✓ Uploaded
                </span>

            </div>


            <div class="employee-document-file">

                <div class="employee-document-file-icon">
                    ${get_file_icon(
                        file.file_name
                    )}
                </div>

                <div class="employee-document-file-info">

                    <div class="employee-document-file-name"
                         title="${escape_html(
                             file.file_name
                         )}">
                        ${escape_html(
                            remove_document_prefix(
                                file.file_name
                            )
                        )}
                    </div>

                    <div class="text-muted">
                        ${format_document_date(
                            file.creation
                        )}
                    </div>

                </div>

            </div>


            <div class="employee-document-actions">

                <button
                    type="button"
                    class="btn btn-sm btn-default employee-document-preview"
                    data-file-name="${escape_html(
                        file.name
                    )}"
                    data-file-url="${escape_html(
                        file.file_url
                    )}"
                >
                    Preview
                </button>


                <button
                    type="button"
                    class="btn btn-sm btn-default employee-document-upload"
                    data-document-type="${document_type}"
                >
                    Replace
                </button>


                <button
                    type="button"
                    class="btn btn-sm btn-danger employee-document-delete"
                    data-file-name="${escape_html(
                        file.name
                    )}"
                >
                    Delete
                </button>

            </div>

        </div>
    `;
}


// ============================================================
// SELECT FILE
// ============================================================

function select_employee_document(
    frm,
    dialog,
    document_type
) {

    const config =
        EMPLOYEE_DOCUMENT_TYPES[
            document_type
        ];


    const input =
        document.createElement("input");


    input.type = "file";

    input.accept =
        config.accept;


    input.onchange =
        async function () {

            const file =
                input.files[0];


            if (!file) {
                return;
            }


            await upload_employee_document(
                frm,
                dialog,
                document_type,
                file
            );
        };


    input.click();
}


// ============================================================
// UPLOAD
// ============================================================

async function upload_employee_document(
    frm,
    dialog,
    document_type,
    file
) {

    const max_size =
        10 * 1024 * 1024;


    if (file.size > max_size) {

        frappe.msgprint({

            title:
                __("File Too Large"),

            message:
                __("Maximum allowed file size is 10 MB."),

            indicator:
                "red"
        });

        return;
    }


    const config =
        EMPLOYEE_DOCUMENT_TYPES[
            document_type
        ];


    try {

        // ----------------------------------------------------
        // Get current files
        // ----------------------------------------------------

        const response =
            await frappe.call({

                method:
                    "employee_document_manager",

                args: {

                    action:
                        "list",

                    employee:
                        frm.doc.name
                }
            });


        const files =
            response.message || [];


        const existing =
            files.find(
                f =>
                    f.document_type ===
                    document_type
            );


        // ----------------------------------------------------
        // Confirm replacement
        // ----------------------------------------------------

        if (existing) {

            const confirmed =
                await confirm_dialog(
                    "A " +
                    config.label +
                    " already exists. Replace it?"
                );


            if (!confirmed) {
                return;
            }


            await delete_employee_file(
                frm.doc.name,
                existing.name
            );
        }


        // ----------------------------------------------------
        // Filename
        // ----------------------------------------------------

        const prefix =
            "[" +
            document_type +
            "] ";


        let file_name =
            file.name;


        if (
            !file_name.startsWith(
                prefix
            )
        ) {

            file_name =
                prefix +
                file_name;
        }


        // ----------------------------------------------------
        // FormData
        // ----------------------------------------------------

        const form_data =
            new FormData();


        form_data.append(
            "file",
            file,
            file_name
        );


        form_data.append(
            "is_private",
            "1"
        );


        form_data.append(
            "folder",
            "Home/Attachments"
        );


        form_data.append(
            "doctype",
            "Employee"
        );


        form_data.append(
            "docname",
            frm.doc.name
        );


        // ----------------------------------------------------
        // Upload
        // ----------------------------------------------------

        frappe.dom.freeze(
            __("Uploading {0}...", [
                config.label
            ])
        );


        const upload_response =
            await fetch(
                "/api/method/upload_file",
                {

                    method:
                        "POST",

                    headers: {

                        "X-Frappe-CSRF-Token":
                            frappe.csrf_token
                    },

                    body:
                        form_data
                }
            );


        const upload_result =
            await upload_response.json();


        if (
            !upload_response.ok ||
            upload_result.exc ||
            !upload_result.message
        ) {

            console.error(
                "Upload response:",
                upload_result
            );


            throw new Error(
                upload_result.exc ||
                "File upload failed"
            );
        }


        frappe.show_alert({

            message:
                config.label +
                " uploaded successfully",

            indicator:
                "green"
        });


        // ----------------------------------------------------
        // Reload
        // ----------------------------------------------------

        await load_employee_documents(
            frm,
            dialog
        );


    } catch (error) {

        console.error(
            "Employee document upload error:",
            error
        );


        frappe.msgprint({

            title:
                __("Upload Failed"),

            message:
                error.message ||
                __("Unable to upload document."),

            indicator:
                "red"
        });


    } finally {

        frappe.dom.unfreeze();
    }
}


// ============================================================
// DELETE
// ============================================================

async function delete_employee_document(
    frm,
    dialog,
    file_name
) {

    const confirmed =
        await confirm_dialog(
            "Are you sure you want to delete this document?"
        );


    if (!confirmed) {
        return;
    }


    try {

        frappe.dom.freeze(
            __("Deleting document...")
        );


        await delete_employee_file(
            frm.doc.name,
            file_name
        );


        frappe.show_alert({

            message:
                __("Document deleted"),

            indicator:
                "green"
        });


        await load_employee_documents(
            frm,
            dialog
        );


    } catch (error) {

        console.error(
            "Delete error:",
            error
        );


        frappe.msgprint({

            title:
                __("Delete Failed"),

            message:
                error.message ||
                __("Unable to delete document."),

            indicator:
                "red"
        });


    } finally {

        frappe.dom.unfreeze();
    }
}


// ============================================================
// DELETE SERVER CALL
// ============================================================

async function delete_employee_file(
    employee,
    file_name
) {

    const response =
        await frappe.call({

            method:
                "employee_document_manager",

            args: {

                action:
                    "delete",

                employee:
                    employee,

                file_name:
                    file_name
            }
        });


    if (
        !response.message ||
        response.message.success !== true
    ) {

        throw new Error(
            "Unable to delete file"
        );
    }


    return response.message;
}


// ============================================================
// PREVIEW
// ============================================================

function preview_employee_document(
    file_name,
    file_url
) {

    if (!file_url) {

        frappe.msgprint(
            __("File URL is not available.")
        );

        return;
    }


    const extension =
        get_file_extension(
            file_name
        );


    const dialog =
        new frappe.ui.Dialog({

            title:
                remove_document_prefix(
                    file_name
                ),

            size:
                "extra-large",

            fields: [

                {
                    fieldtype:
                        "HTML",

                    fieldname:
                        "preview"
                }

            ]
        });


    dialog.show();


    const wrapper =
        dialog.fields_dict
            .preview
            .$wrapper;


    // --------------------------------------------------------
    // PDF
    // --------------------------------------------------------

    if (
        extension === "pdf"
    ) {

        wrapper.html(`

            <div class="employee-document-preview-container">

                <iframe
                    src="${escape_html(
                        file_url
                    )}"
                    class="employee-document-pdf-preview">
                </iframe>

            </div>

        `);

        return;
    }


    // --------------------------------------------------------
    // Images
    // --------------------------------------------------------

    if (
        [
            "jpg",
            "jpeg",
            "png",
            "webp",
            "gif"
        ].includes(extension)
    ) {

        wrapper.html(`

            <div class="employee-document-image-preview">

                <img
                    src="${escape_html(
                        file_url
                    )}"
                    alt="${escape_html(
                        file_name
                    )}"
                />

            </div>

        `);

        return;
    }


    // --------------------------------------------------------
    // Other files
    // --------------------------------------------------------

    wrapper.html(`

        <div class="employee-document-other-preview">

            <div class="employee-document-large-icon">
                📄
            </div>

            <div>
                Preview is not available for this file type.
            </div>

            <a
                href="${escape_html(
                    file_url
                )}"
                target="_blank"
                class="btn btn-primary"
                style="margin-top:15px;"
            >
                Open File
            </a>

        </div>

    `);
}


// ============================================================
// HELPERS
// ============================================================

function get_document_label(
    document_type
) {

    if (
        EMPLOYEE_DOCUMENT_TYPES[
            document_type
        ]
    ) {

        return EMPLOYEE_DOCUMENT_TYPES[
            document_type
        ].label;
    }


    return document_type;
}


function get_file_extension(
    file_name
) {

    if (!file_name) {
        return "";
    }


    const parts =
        file_name
            .toLowerCase()
            .split(".");


    return parts.length > 1
        ? parts.pop()
        : "";
}


function remove_document_prefix(
    file_name
) {

    if (!file_name) {
        return "";
    }


    const match =
        file_name.match(
            /^\[[^\]]+\]\s*/
        );


    if (match) {

        return file_name.substring(
            match[0].length
        );
    }


    return file_name;
}


function format_document_date(
    date
) {

    if (!date) {
        return "";
    }


    try {

        return frappe.datetime
            .str_to_user(date);

    } catch (e) {

        return date;
    }
}


function get_file_icon(
    file_name
) {

    const extension =
        get_file_extension(
            file_name
        );


    if (extension === "pdf") {
        return "📕";
    }


    if (
        [
            "jpg",
            "jpeg",
            "png",
            "webp",
            "gif"
        ].includes(extension)
    ) {
        return "🖼️";
    }


    if (
        [
            "doc",
            "docx"
        ].includes(extension)
    ) {
        return "📘";
    }


    return "📄";
}


function escape_html(
    value
) {

    if (
        value === undefined ||
        value === null
    ) {
        return "";
    }


    return String(value)
        .replace(
            /&/g,
            "&amp;"
        )
        .replace(
            /</g,
            "&lt;"
        )
        .replace(
            />/g,
            "&gt;"
        )
        .replace(
            /"/g,
            "&quot;"
        )
        .replace(
            /'/g,
            "&#039;"
        );
}


function confirm_dialog(
    message
) {

    return new Promise(
        resolve => {

            frappe.confirm(

                __(message),

                function () {
                    resolve(true);
                },

                function () {
                    resolve(false);
                }
            );

        }
    );
}


